import{_ as e,o as a,c as r,an as i}from"./chunks/framework.CKOWAfHB.js";const p=JSON.parse('{"title":"Adjoints and backends","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/adjoints-and-backends.md","filePath":"explanation/adjoints-and-backends.md","lastUpdated":null}'),d={name:"explanation/adjoints-and-backends.md"};function o(l,t,s,n,h,c){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="adjoints-backends" tabindex="-1">Adjoints and backends <a class="header-anchor" href="#adjoints-backends" aria-label="Permalink to &quot;Adjoints and backends {#adjoints-backends}&quot;">​</a></h1><p>This page says which code runs when an AD backend differentiates an operator call, and how executors interact with each backend. For which backend to choose, see <a href="/previews/PR138/benchmarks/ad-comparison#ad-backends">Choosing a backend</a>.</p><h2 id="adjoint-routing" tabindex="-1">Rules and plain AD <a class="header-anchor" href="#adjoint-routing" aria-label="Permalink to &quot;Rules and plain AD {#adjoint-routing}&quot;">​</a></h2><p>Each operator call takes one of two routes:</p><ul><li><p>the rule, a reverse pass written for the operator, which the <a href="/previews/PR138/extensions/mooncake#extension-mooncake">Mooncake</a> and <a href="/previews/PR138/extensions/enzyme#extension-enzyme">Enzyme</a> extensions register with those backends;</p></li><li><p>plain AD, where the backend differentiates the operator&#39;s forward loop.</p></li></ul><p>A call takes the rule when <a href="/previews/PR138/lib/public#ComposableRecurrences.uses_adjoint"><code>uses_adjoint(op, Run())</code></a> is <code>true</code> and every float it holds is a <code>Float16</code>, <code>Float32</code> or <code>Float64</code>. These floats may sit in an <code>Array</code>, a view or reshape of one, a sparse matrix or a <code>Diagonal</code>. Dual numbers, tracked values, <code>BigFloat</code>, abstractly typed fields and other array types take plain AD. The route is read from types, apart from the rebuild check and the strata limit below.</p><p>The rule of a <a href="/previews/PR138/lib/public#ComposableRecurrences.Recurrence"><code>Recurrence</code></a> calls the <a href="/previews/PR138/lib/public#ComposableRecurrences.pullback!"><code>pullback!</code></a> of its coupling and modifiers. A part without one is differentiated inside the rule with a local ForwardDiff step where that is cheap; otherwise the whole operator takes plain AD.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Part without a <code>pullback!</code></th><th style="text-align:right;">Route</th></tr></thead><tbody><tr><td style="text-align:right;">pointwise modifier or depletion form with only scalar float parameters</td><td style="text-align:right;">rule, local ForwardDiff step</td></tr><tr><td style="text-align:right;">pointwise modifier or depletion form with a <code>PerStratum</code>, <code>TimeVarying</code> or array parameter</td><td style="text-align:right;">plain AD</td></tr><tr><td style="text-align:right;">modifier with a vector step</td><td style="text-align:right;">plain AD</td></tr><tr><td style="text-align:right;">coupling with only scalar float parameters, strata plus scalars at most 12</td><td style="text-align:right;">rule, local ForwardDiff step</td></tr><tr><td style="text-align:right;">the same coupling with more than 12</td><td style="text-align:right;">plain AD</td></tr><tr><td style="text-align:right;"><a href="/previews/PR138/lib/public#ComposableRecurrences.Transform"><code>Transform</code></a> whose map holds floats, with no <code>derivative</code></td><td style="text-align:right;">plain AD</td></tr><tr><td style="text-align:right;">part that the local step cannot rebuild from its parameters</td><td style="text-align:right;">plain AD</td></tr></tbody></table><p>A modifier with a <a href="/previews/PR138/lib/public#ComposableRecurrences.Derived"><code>Derived</code></a> parameter whose map holds floats takes plain AD even with a <code>pullback!</code>, as neither reaches those floats.</p><p>The local step rebuilds a part with dual numbers in place of its float parameters; <a href="/previews/PR138/developer/extending#extending">Adding a modifier</a> lists what that needs. The <code>Recurrence</code> constructor checks the rebuild once and stores the result. Above 12 strata and scalars the local step of a coupling needs more than one pass of dual numbers per step.</p><p>Under Mooncake or Enzyme reverse mode, the first call of each operator type that one of these parts sends to plain AD logs an <code>@info</code> saying why. A <code>NoAdjoint</code> call, or one sent to plain AD by its float or array types, logs nothing.</p><h2 id="adjoint-backends" tabindex="-1">Backends <a class="header-anchor" href="#adjoint-backends" aria-label="Permalink to &quot;Backends {#adjoint-backends}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Backend</th><th style="text-align:right;">Rule</th><th style="text-align:right;">Plain AD</th></tr></thead><tbody><tr><td style="text-align:right;">ForwardDiff</td><td style="text-align:right;">never</td><td style="text-align:right;">always, on dual numbers</td></tr><tr><td style="text-align:right;">ReverseDiff</td><td style="text-align:right;">never</td><td style="text-align:right;">always, on tracked values</td></tr><tr><td style="text-align:right;">Mooncake forward</td><td style="text-align:right;">never</td><td style="text-align:right;">always</td></tr><tr><td style="text-align:right;">Enzyme forward</td><td style="text-align:right;">never</td><td style="text-align:right;">always</td></tr><tr><td style="text-align:right;">Mooncake reverse</td><td style="text-align:right;">when the call takes the rule</td><td style="text-align:right;">otherwise</td></tr><tr><td style="text-align:right;">Enzyme reverse</td><td style="text-align:right;">when the call takes the rule</td><td style="text-align:right;">otherwise</td></tr></tbody></table><p>Forward-mode backends run the same forward code on both routes, so a rule only changes the cost of reverse mode. ReverseDiff runs in the AD tests but is not a target.</p><h2 id="rule-policy" tabindex="-1">Which rules are kept <a class="header-anchor" href="#rule-policy" aria-label="Permalink to &quot;Which rules are kept {#rule-policy}&quot;">​</a></h2><p>A rule is kept only where it beats plain AD, its <a href="/previews/PR138/lib/public#ComposableRecurrences.NoAdjoint"><code>NoAdjoint</code></a> twin, by about 10% in reverse mode on Mooncake or Enzyme. The route does not depend on the backend, so a rule that wins on one backend and loses on the other runs on both. The table gives the rule time over the <code>NoAdjoint</code> time, from <a href="/previews/PR138/developer/testing#testing">benchmark matrix</a> cases at <code>T</code> 200 and <code>L</code> 20 where one covers it, else from the small CI scenarios (marked ¹).</p><table tabindex="0"><thead><tr><th style="text-align:right;">Rule switched on by</th><th style="text-align:right;">Mooncake reverse</th><th style="text-align:right;">Enzyme reverse</th><th style="text-align:right;">Decision</th></tr></thead><tbody><tr><td style="text-align:right;">core recurrence (kernel, <code>I</code> or dense coupling)</td><td style="text-align:right;">0.44</td><td style="text-align:right;">0.84</td><td style="text-align:right;">keep</td></tr><tr><td style="text-align:right;"><code>Depletion</code>, hazard form</td><td style="text-align:right;">0.16</td><td style="text-align:right;">0.31</td><td style="text-align:right;">keep</td></tr><tr><td style="text-align:right;"><code>Depletion</code>, <code>Floor()</code>, dense coupling</td><td style="text-align:right;">0.32</td><td style="text-align:right;">0.39</td><td style="text-align:right;">keep</td></tr><tr><td style="text-align:right;"><code>Depletion</code> with removals and <code>Protected</code></td><td style="text-align:right;">0.28</td><td style="text-align:right;">0.40</td><td style="text-align:right;">keep</td></tr><tr><td style="text-align:right;"><code>Redistribute</code></td><td style="text-align:right;">0.26</td><td style="text-align:right;">0.32</td><td style="text-align:right;">keep</td></tr><tr><td style="text-align:right;"><code>Allocate</code></td><td style="text-align:right;">0.78¹</td><td style="text-align:right;">0.78¹</td><td style="text-align:right;">keep</td></tr><tr><td style="text-align:right;"><code>Transform</code></td><td style="text-align:right;">0.18</td><td style="text-align:right;">0.43</td><td style="text-align:right;">keep</td></tr><tr><td style="text-align:right;"><code>Primary()</code> kernel</td><td style="text-align:right;">0.51</td><td style="text-align:right;">0.66</td><td style="text-align:right;">keep</td></tr><tr><td style="text-align:right;"><code>Pairwise</code> kernel</td><td style="text-align:right;">0.68¹</td><td style="text-align:right;">0.61¹</td><td style="text-align:right;">keep</td></tr><tr><td style="text-align:right;"><code>Diagonal</code> coupling</td><td style="text-align:right;">0.84¹</td><td style="text-align:right;">0.98¹</td><td style="text-align:right;">keep</td></tr><tr><td style="text-align:right;">sparse coupling</td><td style="text-align:right;">0.75¹</td><td style="text-align:right;">plain AD is wrong</td><td style="text-align:right;">keep</td></tr><tr><td style="text-align:right;"><code>TimeVarying</code> kernel and coupling</td><td style="text-align:right;">0.71¹</td><td style="text-align:right;">0.85¹</td><td style="text-align:right;">keep</td></tr><tr><td style="text-align:right;"><code>Convolution</code></td><td style="text-align:right;">0.48</td><td style="text-align:right;">0.64</td><td style="text-align:right;">keep</td></tr><tr><td style="text-align:right;">pointwise modifier without a <code>pullback!</code></td><td style="text-align:right;">0.64</td><td style="text-align:right;">1.12</td><td style="text-align:right;">keep, slower on Enzyme</td></tr><tr><td style="text-align:right;">coupling without a <code>pullback!</code>, up to 12 strata and scalars</td><td style="text-align:right;">0.64²</td><td style="text-align:right;">0.68²</td><td style="text-align:right;">keep</td></tr></tbody></table><p>² The worst of 3 and 10 strata for a user type, at <code>T</code> 200 and <code>L</code> 20.</p><p>Every rule in the table is faster than plain AD on both backends, where plain AD is right, except the local step of a pointwise modifier. That step is kept for Mooncake, so it also runs on Enzyme, where it is 1.12 to 1.38 times slower than plain AD. On Mooncake it wins at <code>T</code> 200 and <code>L</code> 20 but is within noise or slower at small sizes. A coupling whose cost grows with the strata squared was 1.7 to 4 times slower than plain AD on Enzyme from 16 strata, hence the limit of 12.</p><h2 id="adjoint-checks" tabindex="-1">Checking a rule <a class="header-anchor" href="#adjoint-checks" aria-label="Permalink to &quot;Checking a rule {#adjoint-checks}&quot;">​</a></h2><p><a href="/previews/PR138/lib/public#ComposableRecurrences.NoAdjoint"><code>NoAdjoint(op)</code></a> sends every call of <code>op</code> to plain AD, to compare gradients and times with the rule. <a href="/previews/PR138/developer/testing#compare-plain-ad">Testing and benchmarking</a> shows how. <a href="/previews/PR138/lib/public#ComposableRecurrences.test_adjoint"><code>test_adjoint</code></a> runs a backend&#39;s own rule tester on an operator&#39;s rule.</p><h2 id="executors" tabindex="-1">Executors <a class="header-anchor" href="#executors" aria-label="Permalink to &quot;Executors {#executors}&quot;">​</a></h2><p>An executor sets how an operator&#39;s loops over strata, series or output times run. <a href="/previews/PR138/lib/public#ComposableRecurrences.EXECUTOR"><code>EXECUTOR</code></a> holds the one in use, <a href="/previews/PR138/lib/public#ComposableRecurrences.Serial"><code>Serial</code></a> by default. <a href="/previews/PR138/lib/public#ComposableRecurrences.Threaded"><code>Threaded</code></a> splits a loop across CPU threads, and <a href="/previews/PR138/lib/public#ComposableRecurrences.Device"><code>Device</code></a> runs it as a kernel on a GPU. A new executor is a subtype of <a href="/previews/PR138/lib/public#ComposableRecurrences.Executor"><code>Executor</code></a> with a method of <a href="/previews/PR138/lib/public#ComposableRecurrences.each!"><code>each!</code></a>.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Executor</th><th style="text-align:right;">Forward</th><th style="text-align:right;">ForwardDiff</th><th style="text-align:right;">ReverseDiff</th><th style="text-align:right;">Mooncake, Enzyme forward</th><th style="text-align:right;">Mooncake, Enzyme reverse</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Serial()</code></td><td style="text-align:right;">all operators</td><td style="text-align:right;">yes</td><td style="text-align:right;">yes</td><td style="text-align:right;">yes</td><td style="text-align:right;">yes</td></tr><tr><td style="text-align:right;"><code>Threaded()</code></td><td style="text-align:right;">all operators</td><td style="text-align:right;">yes, threaded</td><td style="text-align:right;">not tested</td><td style="text-align:right;">yes, serial</td><td style="text-align:right;">rule&#39;s forward pass threaded, all else serial</td></tr><tr><td style="text-align:right;"><code>Device(backend)</code></td><td style="text-align:right;">convolutions; recurrences with an <code>I</code> coupling and no modifiers, <code>Add</code> or <code>Clamp</code></td><td style="text-align:right;">not tested</td><td style="text-align:right;">not tested</td><td style="text-align:right;">not tested</td><td style="text-align:right;">not tested</td></tr></tbody></table><p>Mooncake and Enzyme do not differentiate tasks, so code they trace runs serially whatever executor is set. A rule&#39;s forward pass is not traced, so it uses the set executor. Its reverse pass runs on the calling task, because it adds every stratum&#39;s terms into shared kernel and parameter cotangents. The <code>Device(backend)</code> row was checked on JLArrays only; the <a href="/previews/PR138/lib/public#ComposableRecurrences.Device"><code>Device</code></a> docstring lists what does not run on a device.</p>',25)])])}const y=e(d,[["render",o]]);export{p as __pageData,y as default};
